def exampleTool(**_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # This tool accepts no parameters at all. If toolchain passes anything, error.
    if _extra:
        return _err("VALIDATION_ERROR", "exampleTool accepts no parameters.", unexpected_parameters=sorted(list(_extra.keys())))

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Observable service dynamics: record call if request log exists.
    # Schema did not declare a request log collection; no mutation required by business rules.
    latency_ms = int((time.time() - t0) * 1000)

    return {
        "tool": "exampleTool",
        "ok": True,
        "message": "Gemini Server reachable.",
        "timestamp": now,
        "latency_ms": latency_ms,
    }

def gemini_generateContent(api_key_id, model, prompt=None, contents=None, generation_config=None, safety_settings=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    # ---- Validate inputs (types/enums/patterns) ----
    if _extra:
        return _err("VALIDATION_ERROR", "Unexpected parameters provided.", unexpected_parameters=sorted(list(_extra.keys())))
    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.", field="api_key_id")
    if not isinstance(model, str) or not model.strip():
        return _err("VALIDATION_ERROR", "Invalid model.", field="model")
    if prompt is not None and not isinstance(prompt, str):
        return _err("VALIDATION_ERROR", "prompt must be a string.", field="prompt")
    if contents is not None and not isinstance(contents, dict):
        return _err("VALIDATION_ERROR", "contents must be an object.", field="contents")
    if generation_config is not None and not isinstance(generation_config, dict):
        return _err("VALIDATION_ERROR", "generation_config must be an object.", field="generation_config")
    if safety_settings is not None and not isinstance(safety_settings, list):
        return _err("VALIDATION_ERROR", "safety_settings must be an array.", field="safety_settings")
    if safety_settings is not None:
        for i, it in enumerate(safety_settings):
            if not isinstance(it, dict):
                return _err("VALIDATION_ERROR", "Each safety_settings item must be an object.", field=f"safety_settings[{i}]")

    # Require at least one of prompt/contents (contents takes precedence when provided)
    if contents is None and (prompt is None or not prompt.strip()):
        return _err("VALIDATION_ERROR", "Either contents or a non-empty prompt must be provided.", field="prompt")

    # ---- Load datastore ----
    api_keys = _load("api_keys.json")
    gen_reqs = _load("generation_requests.json")

    # ---- Resolve credential ----
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("NOT_FOUND", "api_key_id not found.", field="api_key_id")

    # ---- Create generation request row (queued) ----
    req_id = "gmr_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "gemini_generateContent",
        "model": model,
        "is_stream": False,
        "chat_session_id": None,
        "prompt_text": None if contents is not None else prompt,
        "contents": contents,
        "generation_config": generation_config,
        "safety_settings": safety_settings,
        "tools_declarations": None,
        "function_call_request": None,
        "response_text": None,
        "response_raw": None,
        "usage": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    gen_reqs.append(req_row)
    _save("generation_requests.json", gen_reqs)

    # Helper to persist status transitions with timestamps
    allowed = {
        "queued": set(["running", "cancelled", "failed"]),
        "running": set(["succeeded", "failed", "cancelled"]),
        "succeeded": set([]),
        "failed": set([]),
        "cancelled": set([]),
    }
    def _transition(to_status, error_code=None, error_message=None, response_text=None, response_raw=None, usage=None):
        nonlocal gen_reqs, req_row, now_dt
        # reload latest to avoid stomping
        gen_reqs = _load("generation_requests.json")
        rr = next((r for r in gen_reqs if r.get("id") == req_id), None)
        if not rr:
            return False, _err("NOT_FOUND", "generation request not found during transition.", id=req_id)
        frm = rr.get("status")
        if to_status not in allowed.get(frm, set()):
            return False, _err("INVALID_TRANSITION", "Illegal status transition.", from_status=frm, to_status=to_status)
        rr["status"] = to_status
        rr["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        if to_status == "running":
            rr["started_at"] = rr["updated_at"]
        if to_status in ("succeeded", "failed", "cancelled"):
            rr["completed_at"] = rr["updated_at"]
        if error_code is not None:
            rr["error_code"] = error_code
        if error_message is not None:
            rr["error_message"] = error_message
        if response_text is not None:
            rr["response_text"] = response_text
        if response_raw is not None:
            rr["response_raw"] = response_raw
        if usage is not None:
            rr["usage"] = usage
        _save("generation_requests.json", gen_reqs)
        req_row = rr
        return True, None

    # ---- Enforce key status ----
    if key.get("status") != "active":
        _transition("failed", error_code="key_disabled", error_message="API key is not active.")
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "id": req_id,
            "status": "failed",
            "model": model,
            "error": {"code": "key_disabled", "message": "API key is not active."},
            "latency_ms": latency_ms,
        }

    # ---- Quota enforcement (requests + tokens projection) ----
    # Projected tokens: if generation_config.maxOutputTokens exists use that else a conservative estimate
    max_out = None
    if isinstance(generation_config, dict):
        mot = generation_config.get("maxOutputTokens")
        if isinstance(mot, int) and mot >= 0:
            max_out = mot
    # Rough prompt token projection (offline): chars/4, at least 1 if any input
    in_text = None
    if contents is not None:
        try:
            in_text = json.dumps(contents, ensure_ascii=False)
        except Exception:
            in_text = None
    else:
        in_text = prompt or ""
    approx_in_tokens = max(1, int(len(in_text) / 4)) if in_text else 0
    projected_tokens = approx_in_tokens + (max_out if max_out is not None else 256)

    # Validate counters and limits are non-negative ints
    for fld in ("daily_request_limit", "daily_token_limit", "requests_today", "tokens_today"):
        if not isinstance(key.get(fld), int) or key.get(fld) < 0:
            _transition("failed", error_code="key_invalid", error_message=f"Key field {fld} is invalid.")
            return _err("CONFLICT", "API key has invalid quota configuration.", field=fld)

    if key["requests_today"] + 1 > key["daily_request_limit"] or key["tokens_today"] + projected_tokens > key["daily_token_limit"]:
        _transition("failed", error_code="quota_exceeded", error_message="Daily quota exceeded.")
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "id": req_id,
            "status": "failed",
            "model": model,
            "error": {"code": "quota_exceeded", "message": "Daily quota exceeded."},
            "latency_ms": latency_ms,
        }

    # Consume quota up-front (soft quota)
    api_keys = _load("api_keys.json")
    k2 = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not k2:
        _transition("failed", error_code="key_missing", error_message="API key disappeared.")
        return _err("NOT_FOUND", "api_key_id not found.", field="api_key_id")
    k2["requests_today"] = int(k2.get("requests_today", 0)) + 1
    k2["tokens_today"] = int(k2.get("tokens_today", 0)) + projected_tokens
    k2["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("api_keys.json", api_keys)

    # ---- Run -> Succeed (offline simulated upstream) ----
    ok, e = _transition("running")
    if not ok:
        return e

    # Simulated response
    user_visible_prompt = in_text if in_text is not None else ""
    response_text = f"[simulated gemini response] model={model}\n{user_visible_prompt[:2000]}"
    usage = {"input_tokens": approx_in_tokens, "output_tokens": (max_out if max_out is not None else 256), "total_tokens": projected_tokens}
    response_raw = {
        "provider": key.get("provider"),
        "model": model,
        "finishReason": "STOP",
        "simulated": True,
    }

    ok, e = _transition("succeeded", response_text=response_text, response_raw=response_raw, usage=usage)
    if not ok:
        return e

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "id": req_id,
        "status": "succeeded",
        "model": model,
        "text": response_text,
        "raw": response_raw,
        "usage": usage,
        "latency_ms": latency_ms,
    }

