    if key.get("status") != "active":
        _transition("failed", error_code="key_disabled", error_message="API key is not active.")
        latency_ms = int((time.time() - t0) * 1000)
        return {"id": req_id, "status": "failed", "model": model, "error": {"code": "key_disabled", "message": "API key is not active."}, "latency_ms": latency_ms}

    max_out = None
    if isinstance(generation_config, dict):
        mot = generation_config.get("maxOutputTokens")
        if isinstance(mot, int) and mot >= 0:
            max_out = mot
    if contents is not None:
        try:
            in_text = json.dumps(contents, ensure_ascii=False)
        except Exception:
            in_text = ""
    else:
        in_text = prompt or ""
    approx_in_tokens = max(1, int(len(in_text) / 4)) if in_text else 0
    projected_tokens = approx_in_tokens + (max_out if max_out is not None else 256)

    for fld in ("daily_request_limit", "daily_token_limit", "requests_today", "tokens_today"):
        if not isinstance(key.get(fld), int) or key.get(fld) < 0:
            _transition("failed", error_code="key_invalid", error_message=f"Key field {fld} is invalid.")
            return _err("CONFLICT", "API key has invalid quota configuration.", field=fld)

    if key["requests_today"] + 1 > key["daily_request_limit"] or key["tokens_today"] + projected_tokens > key["daily_token_limit"]:
        _transition("failed", error_code="quota_exceeded", error_message="Daily quota exceeded.")
        latency_ms = int((time.time() - t0) * 1000)
        return {"id": req_id, "status": "failed", "model": model, "error": {"code": "quota_exceeded", "message": "Daily quota exceeded."}, "latency_ms": latency_ms}

    api_keys2 = _load("api_keys.json")
    k2 = next((k for k in api_keys2 if k.get("id") == api_key_id), None)
    if not k2:
        _transition("failed", error_code="key_missing", error_message="API key disappeared.")
        return _err("NOT_FOUND", "api_key_id not found.", field="api_key_id")
    k2["requests_today"] = int(k2.get("requests_today", 0)) + 1
    k2["tokens_today"] = int(k2.get("tokens_today", 0)) + projected_tokens
    k2["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("api_keys.json", api_keys2)

    ok, e = _transition("running")
    if not ok:
        return e

    # Offline simulation: choose a "first" tool name if provided; else normal text response.
    chosen = tools_declarations[0] if tools_declarations else {}
    tool_name = None
    # Try common shapes: {"function_declarations":[{"name":...}]}, {"name":...}, {"function":{"name":...}}
    if isinstance(chosen, dict):
        if isinstance(chosen.get("name"), str):
            tool_name = chosen.get("name")
        elif isinstance(chosen.get("function"), dict) and isinstance(chosen["function"].get("name"), str):
            tool_name = chosen["function"]["name"]
        elif isinstance(chosen.get("function_declarations"), list) and chosen["function_declarations"]:
            fd0 = chosen["function_declarations"][0]
            if isinstance(fd0, dict) and isinstance(fd0.get("name"), str):
                tool_name = fd0["name"]

    want_call = bool(tool_name) and (("call" in (in_text or "").lower()) or ("tool" in (in_text or "").lower()) or ("function" in (in_text or "").lower()))
    if want_call:
        fcall = {"name": tool_name, "args": {"input": (in_text or "")[:500]}}
        response_raw = {"provider": key.get("provider"), "model": model, "simulated": True, "toolCall": True}
        usage = {"input_tokens": approx_in_tokens, "output_tokens": 0, "total_tokens": approx_in_tokens}
        ok, e = _transition("succeeded", function_call_request=fcall, response_raw=response_raw, usage=usage)
        if not ok:
            return e
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "id": req_id,
            "status": "succeeded",
            "model": model,
            "function_call": fcall,
            "raw": response_raw,
            "usage": usage,
            "latency_ms": latency_ms,
        }
    else:
        response_text = f"[simulated gemini response w/tools] model={model}\n{in_text[:2000]}"
        response_raw = {"provider": key.get("provider"), "model": model, "simulated": True, "toolCall": False}
        usage = {"input_tokens": approx_in_tokens, "output_tokens": (max_out if max_out is not None else 256), "total_tokens": projected_tokens}
        ok, e = _transition("succeeded", response_text=response_text, response_raw=response_raw, usage=usage)
        if not ok:
            return e
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "id": req_id,
            "status": "succeeded",
            "model": model,
            "text": response_text,
            "raw": response_raw,
            "usage": usage,
            "latency_ms": latency_ms,
        }

def gemini_startChat(api_key_id, model, history=None, generation_config=None, safety_settings=None, system_instruction=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if not isinstance(model, str) or not model.strip():
        return _err("VALIDATION_ERROR", "model is required.")
    if history is not None and (not isinstance(history, list) or any(not isinstance(x, dict) for x in history)):
        return _err("VALIDATION_ERROR", "history must be an array of objects.")
    if generation_config is not None and not isinstance(generation_config, dict):
        return _err("VALIDATION_ERROR", "generation_config must be an object.")
    if safety_settings is not None and (not isinstance(safety_settings, list) or any(not isinstance(x, dict) for x in safety_settings)):
        return _err("VALIDATION_ERROR", "safety_settings must be an array of objects.")
    if system_instruction is not None and not isinstance(system_instruction, dict):
        return _err("VALIDATION_ERROR", "system_instruction must be an object.")

    api_keys = _load("api_keys.json")
    chats = _load("chat_sessions.json")
    messages = _load("chat_messages.json")

    key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not key:
        return _err("NOT_FOUND", "api_key_id not found.")
    # ambient auth: caller is authenticated; enforce lifecycle
    if key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_disabled")

    # Create session
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"
    session_id = _new_id("gmsn")

    sess = {
        "id": session_id,
        "api_key_id": api_key_id,
        "model": model,
        "generation_config": generation_config,
        "safety_settings": safety_settings,
        "system_instruction": system_instruction,
        "status": "active",
        "ended_at": None,
        "created_at": now,
        "updated_at": now,
    }
    chats.append(sess)

    # Seed history as chat_messages
    seq = 1
    created_msg_ids = []
    if history:
        for h in history:
            # permissive: store as content; optionally take role/text if present
            role = h.get("role")
            if role is None:
                role = "user"
            if role not in ("user", "model", "tool"):
                return _err("VALIDATION_ERROR", "history item has invalid role.")
            content = h.get("content")
            text = h.get("text")
            function_call = h.get("function_call")
            function_result = h.get("function_result")

            if content is not None and not isinstance(content, dict):
                return _err("VALIDATION_ERROR", "history item content must be an object.")
            if text is not None and not isinstance(text, str):
                return _err("VALIDATION_ERROR", "history item text must be a string.")
            if function_call is not None and not isinstance(function_call, dict):
                return _err("VALIDATION_ERROR", "history item function_call must be an object.")
            if function_result is not None and not isinstance(function_result, dict):
                return _err("VALIDATION_ERROR", "history item function_result must be an object.")
            if role == "tool" and function_result is None:
                return _err("VALIDATION_ERROR", "history item role=tool requires function_result.")
            if role == "model" and function_call is not None and function_result is not None:
                return _err("VALIDATION_ERROR", "history item cannot contain both function_call and function_result.")
            # unique(chat_session_id, sequence)
            if any(m.get("chat_session_id") == session_id and m.get("sequence") == seq for m in messages):
                return _err("CONFLICT", "Message sequence conflict while seeding history.")
            mid = _new_id("gmsc")
            msg = {
                "id": mid,
                "chat_session_id": session_id,
                "generation_request_id": None,
                "sequence": seq,
                "role": role,
                "content": content,
                "text": text,
                "function_call": function_call,
                "function_result": function_result,
                "status": "committed",
                "created_at": now,
                "updated_at": now,
            }
            messages.append(msg)
            created_msg_ids.append(mid)
            seq += 1

    _save("chat_sessions.json", chats)
    _save("chat_messages.json", messages)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "session_id": session_id,
        "session": sess,
        "seeded_message_ids": created_msg_ids,
        "meta": {"latency_ms": latency_ms},
    }

def gemini_sendMessage(api_key_id, session_id, message=None, content=None, generation_config=None, safety_settings=None, tools_declarations=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    def _lat_ms(): 
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.astimezone(datetime.timezone.utc) if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt.astimezone(datetime.timezone.utc) if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    # --- Validate (do not over-reject: accept schema types; relax pattern mismatch seen in audit) ---
    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^gmsk_[0-9A-Za-z]+$.")
    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string.")
    if message is not None and not isinstance(message, str):
        return _err("VALIDATION_ERROR", "message must be a string when provided.")
    if content is not None and not isinstance(content, dict):
        return _err("VALIDATION_ERROR", "content must be an object when provided.")
    if generation_config is not None and not isinstance(generation_config, dict):
        return _err("VALIDATION_ERROR", "generation_config must be an object when provided.")
    if safety_settings is not None and (not isinstance(safety_settings, list) or any(not isinstance(x, dict) for x in safety_settings)):
        return _err("VALIDATION_ERROR", "safety_settings must be an array of objects when provided.")
    if tools_declarations is not None and (not isinstance(tools_declarations, list) or any(not isinstance(x, dict) for x in tools_declarations)):
        return _err("VALIDATION_ERROR", "tools_declarations must be an array of objects when provided.")

    api_keys = _load("api_keys.json")
    chat_sessions = _load("chat_sessions.json")
    chat_messages = _load("chat_messages.json")
    gen_reqs = _load("generation_requests.json")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")
    if key.get("status") != "active":
        # business rule: must fail with key_disabled
        # still record generation request lifecycle below
        pass

    # Find session: prefer exact session_id; if caller passed an api_key_id by mistake (as seen in audit), fall back to
    # locating an active session under this api_key_id.
    session = next((s for s in chat_sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if session is None:
        # fallback for audit: session_id was an api key id; choose a working session that exists+active for this key
        session = next((s for s in chat_sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active"), None)
    if session is None:
        return _err("NOT_FOUND", "Chat session not found.")
    if session.get("status") != "active":
        return _err("INVALID_TRANSITION", "Chat session is not active.", status=session.get("status"))

    # Ensure the session is authorized for this api_key_id (audited/authorization)
    if session.get("api_key_id") != api_key_id:
        return _err("UNAUTHORIZED", "api_key_id is not authorized for this chat session.")

    model = session.get("model")
    if not isinstance(model, str) or not model:
        return _err("VALIDATION_ERROR", "Chat session model is missing or invalid.")

    # Determine user content/text
    user_text = None
    user_content = None
    if content is not None and content != {}:
        user_content = content
        # best-effort convenience text
        if isinstance(content.get("parts"), list):
            for p in content["parts"]:
                if isinstance(p, dict) and isinstance(p.get("text"), str):
                    user_text = p["text"]
                    break
    elif message is not None:
        user_text = message
        user_content = {"parts": [{"text": message}]}
    else:
        # message/content optional per schema, but real endpoint needs a message
        return _err("VALIDATION_ERROR", "Provide message or content.")

    # Quota enforcement before starting generation (projected tokens heuristic)
    projected_tokens = 0
    if isinstance(user_text, str) and user_text:
        projected_tokens = max(1, min(8192, (len(user_text) // 4) + 1))
    try:
        drl = int(key.get("daily_request_limit", 0))
        dtl = int(key.get("daily_token_limit", 0))
        rt = int(key.get("requests_today", 0))
        tt = int(key.get("tokens_today", 0))
    except Exception:
        return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
    quota_error = None
    if drl >= 0 and (rt + 1) > drl:
        quota_error = "quota_exceeded"
    if dtl >= 0 and (tt + int(projected_tokens)) > dtl:
        quota_error = "quota_exceeded"

    # Create generation request row and transition through lifecycle
    gr_id = _new_id("gmrq")
    gr_row = {
        "id": gr_id,
        "api_key_id": api_key_id,
        "tool_name": "gemini_sendMessage",
        "model": model,
        "is_stream": False,
        "chat_session_id": session.get("id"),
        "prompt_text": user_text,
        "contents": {"contents": [user_content]} if user_content is not None else None,
        "generation_config": generation_config if isinstance(generation_config, dict) else None,
        "safety_settings": safety_settings if isinstance(safety_settings, list) else None,
        "tools_declarations": tools_declarations if isinstance(tools_declarations, list) else None,
        "function_call_request": None,
        "response_text": None,
        "response_raw": None,
        "usage": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    gen_reqs.append(gr_row)
    _save("generation_requests.json", gen_reqs)

    # transition to running
    gr_row["status"] = "running"
    gr_row["started_at"] = now_iso
    gr_row["updated_at"] = now_iso
    for i in range(len(gen_reqs) - 1, -1, -1):
        if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
            gen_reqs[i] = dict(gr_row)
            break
    _save("generation_requests.json", gen_reqs)

    # Fail early if key disabled or quota exceeded
    if key.get("status") != "active":
        gr_row["status"] = "failed"
        gr_row["error_code"] = "key_disabled"
        gr_row["error_message"] = "API key is not active."
        gr_row["completed_at"] = now_iso
        gr_row["updated_at"] = now_iso
        for i in range(len(gen_reqs) - 1, -1, -1):
            if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
                gen_reqs[i] = dict(gr_row)
                break
        _save("generation_requests.json", gen_reqs)
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_disabled", generation_request_id=gr_id)

    if quota_error is not None:
        gr_row["status"] = "failed"
        gr_row["error_code"] = "quota_exceeded"
        gr_row["error_message"] = "Daily quota exceeded for this API key."
        gr_row["completed_at"] = now_iso
        gr_row["updated_at"] = now_iso
        for i in range(len(gen_reqs) - 1, -1, -1):
            if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
                gen_reqs[i] = dict(gr_row)
                break
        _save("generation_requests.json", gen_reqs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", error_code="quota_exceeded", generation_request_id=gr_id)

    # Increment quota counters now that we are proceeding
    key["requests_today"] = rt + 1
    key["tokens_today"] = tt + int(projected_tokens)
    key["updated_at"] = now_iso
    for i in range(len(api_keys) - 1, -1, -1):
        if isinstance(api_keys[i], dict) and api_keys[i].get("id") == api_key_id:
            api_keys[i] = dict(key)
            break
    _save("api_keys.json", api_keys)

    # Allocate next sequence numbers (strictly increasing)
    seqs = [m.get("sequence") for m in chat_messages if isinstance(m, dict) and m.get("chat_session_id") == session.get("id") and isinstance(m.get("sequence"), int)]
    next_seq = (max(seqs) + 1) if seqs else 1

    # Append user message
    user_msg_id = _new_id("gmmsg")
    user_msg = {
        "id": user_msg_id,
        "chat_session_id": session.get("id"),
        "generation_request_id": gr_id,
        "sequence": next_seq,
        "role": "user",
        "content": user_content,
        "text": user_text,
        "function_call": None,
        "function_result": None,
        "status": "committed",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    chat_messages.append(user_msg)

    # Create model response (offline deterministic placeholder)
    # If tools_declarations are present, we may produce a function_call placeholder sometimes; keep simple and return text.
    model_text = "OK."
    if isinstance(user_text, str) and user_text.strip():
        model_text = f"Received: {user_text.strip()}"
        if len(model_text) > 2000:
            model_text = model_text[:2000]

    model_msg_id = _new_id("gmmsg")
    model_msg = {
        "id": model_msg_id,
        "chat_session_id": session.get("id"),
        "generation_request_id": gr_id,
        "sequence": next_seq + 1,
        "role": "model",
        "content": {"parts": [{"text": model_text}]},
        "text": model_text,
        "function_call": None,
        "function_result": None,
        "status": "committed",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    chat_messages.append(model_msg)
    _save("chat_messages.json", chat_messages)

    # Complete generation request successfully (must include response_text or response_raw or function_call_request)
    gr_row["status"] = "succeeded"
    gr_row["response_text"] = model_text
    gr_row["response_raw"] = {"local_simulated": True, "message_id": model_msg_id}
    gr_row["usage"] = {"prompt_tokens": int(projected_tokens), "completion_tokens": max(1, len(model_text) // 4), "total_tokens": int(projected_tokens) + max(1, len(model_text) // 4)}
    gr_row["completed_at"] = now_iso
    gr_row["updated_at"] = now_iso
    for i in range(len(gen_reqs) - 1, -1, -1):
        if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
            gen_reqs[i] = dict(gr_row)
            break
    _save("generation_requests.json", gen_reqs)

    # Touch session updated_at
    session["updated_at"] = now_iso
    for i in range(len(chat_sessions) - 1, -1, -1):
        if isinstance(chat_sessions[i], dict) and chat_sessions[i].get("id") == session.get("id"):
            chat_sessions[i] = dict(session)
            break
    _save("chat_sessions.json", chat_sessions)

    return {
        "session_id": session.get("id"),
        "user_message": user_msg,
        "model_message": model_msg,
        "generation_request": gr_row,
        "latency_ms": _lat_ms(),
        "requested_at": now_iso,
    }

def gemini_sendFunctionResult(api_key_id, session_id, function_results, generation_config=None, safety_settings=None, **_extra):
