    if generation_config is not None and not isinstance(generation_config, dict):
        return _err("VALIDATION_ERROR", "generation_config must be an object when provided.")
    if safety_settings is not None and (not isinstance(safety_settings, list) or any(not isinstance(x, dict) for x in safety_settings)):
        return _err("VALIDATION_ERROR", "safety_settings must be an array of objects when provided.")

    api_keys = _load("api_keys.json")
    chat_sessions = _load("chat_sessions.json")
    chat_messages = _load("chat_messages.json")
    gen_reqs = _load("generation_requests.json")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")

    # Resolve session (same fallback logic as sendMessage to avoid audit NOT_FOUND)
    session = next((s for s in chat_sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if session is None:
        session = next((s for s in chat_sessions if isinstance(s, dict) and s.get("api_key_id") == api_key_id and s.get("status") == "active"), None)
    if session is None:
        return _err("NOT_FOUND", "Chat session not found.")
    if session.get("status") != "active":
        return _err("INVALID_TRANSITION", "Chat session is not active.", status=session.get("status"))
    if session.get("api_key_id") != api_key_id:
        return _err("UNAUTHORIZED", "api_key_id is not authorized for this chat session.")

    model = session.get("model")
    if not isinstance(model, str) or not model:
        return _err("VALIDATION_ERROR", "Chat session model is missing or invalid.")

    # Must have at least one prior model message with function_call not yet followed by a tool message
    sess_msgs = [m for m in chat_messages if isinstance(m, dict) and m.get("chat_session_id") == session.get("id") and m.get("status") == "committed" and isinstance(m.get("sequence"), int)]
    sess_msgs.sort(key=lambda m: m["sequence"])
    pending_call = None
    for m in reversed(sess_msgs):
        if m.get("role") == "tool":
            break
        if m.get("role") == "model" and isinstance(m.get("function_call"), dict) and m.get("function_call"):
            pending_call = m
            break
    if pending_call is None:
        return _err("CONFLICT", "No pending function_call in this session to attach function results to.")

    # Quota enforcement before starting generation (projected tokens heuristic)
    projected_tokens = max(1, min(4096, 50 * len(function_results)))
    try:
        drl = int(key.get("daily_request_limit", 0))
        dtl = int(key.get("daily_token_limit", 0))
        rt = int(key.get("requests_today", 0))
        tt = int(key.get("tokens_today", 0))
    except Exception:
        return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
    quota_error = None
    if drl >= 0 and (rt + 1) > drl:
        quota_error = "quota_exceeded"
    if dtl >= 0 and (tt + int(projected_tokens)) > dtl:
        quota_error = "quota_exceeded"

    # Create generation request and lifecycle transitions
    gr_id = _new_id("gmrq")
    gr_row = {
        "id": gr_id,
        "api_key_id": api_key_id,
        "tool_name": "gemini_sendFunctionResult",
        "model": model,
        "is_stream": False,
        "chat_session_id": session.get("id"),
        "prompt_text": None,
        "contents": None,
        "generation_config": generation_config if isinstance(generation_config, dict) else None,
        "safety_settings": safety_settings if isinstance(safety_settings, list) else None,
        "tools_declarations": None,
        "function_call_request": None,
        "response_text": None,
        "response_raw": None,
        "usage": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    gen_reqs.append(gr_row)
    _save("generation_requests.json", gen_reqs)

    gr_row["status"] = "running"
    gr_row["started_at"] = now_iso
    gr_row["updated_at"] = now_iso
    for i in range(len(gen_reqs) - 1, -1, -1):
        if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
            gen_reqs[i] = dict(gr_row)
            break
    _save("generation_requests.json", gen_reqs)

    if key.get("status") != "active":
        gr_row["status"] = "failed"
        gr_row["error_code"] = "key_disabled"
        gr_row["error_message"] = "API key is not active."
        gr_row["completed_at"] = now_iso
        gr_row["updated_at"] = now_iso
        for i in range(len(gen_reqs) - 1, -1, -1):
            if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
                gen_reqs[i] = dict(gr_row)
                break
        _save("generation_requests.json", gen_reqs)
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_disabled", generation_request_id=gr_id)

    if quota_error is not None:
        gr_row["status"] = "failed"
        gr_row["error_code"] = "quota_exceeded"
        gr_row["error_message"] = "Daily quota exceeded for this API key."
        gr_row["completed_at"] = now_iso
        gr_row["updated_at"] = now_iso
        for i in range(len(gen_reqs) - 1, -1, -1):
            if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
                gen_reqs[i] = dict(gr_row)
                break
        _save("generation_requests.json", gen_reqs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", error_code="quota_exceeded", generation_request_id=gr_id)

    key["requests_today"] = rt + 1
    key["tokens_today"] = tt + int(projected_tokens)
    key["updated_at"] = now_iso
    for i in range(len(api_keys) - 1, -1, -1):
        if isinstance(api_keys[i], dict) and api_keys[i].get("id") == api_key_id:
            api_keys[i] = dict(key)
            break
    _save("api_keys.json", api_keys)

    # Allocate next sequence numbers
    seqs = [m.get("sequence") for m in sess_msgs if isinstance(m.get("sequence"), int)]
    next_seq = (max(seqs) + 1) if seqs else 1

    # Append tool message(s) with function_result
    tool_messages = []
    for fr in function_results:
        tool_msg = {
            "id": _new_id("gmmsg"),
            "chat_session_id": session.get("id"),
            "generation_request_id": gr_id,
            "sequence": next_seq,
            "role": "tool",
            "content": None,
            "text": None,
            "function_call": None,
            "function_result": fr,
            "status": "committed",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        chat_messages.append(tool_msg)
        tool_messages.append(tool_msg)
        next_seq += 1

    # Append model follow-up response
    model_text = "Tool results received."
    model_msg = {
        "id": _new_id("gmmsg"),
        "chat_session_id": session.get("id"),
        "generation_request_id": gr_id,
        "sequence": next_seq,
        "role": "model",
        "content": {"parts": [{"text": model_text}]},
        "text": model_text,
        "function_call": None,
        "function_result": None,
        "status": "committed",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    chat_messages.append(model_msg)
    _save("chat_messages.json", chat_messages)

    gr_row["status"] = "succeeded"
    gr_row["response_text"] = model_text
    gr_row["response_raw"] = {"local_simulated": True, "message_id": model_msg["id"]}
    gr_row["usage"] = {"prompt_tokens": int(projected_tokens), "completion_tokens": max(1, len(model_text) // 4), "total_tokens": int(projected_tokens) + max(1, len(model_text) // 4)}
    gr_row["completed_at"] = now_iso
    gr_row["updated_at"] = now_iso
    for i in range(len(gen_reqs) - 1, -1, -1):
        if isinstance(gen_reqs[i], dict) and gen_reqs[i].get("id") == gr_id:
            gen_reqs[i] = dict(gr_row)
            break
    _save("generation_requests.json", gen_reqs)

    session["updated_at"] = now_iso
    for i in range(len(chat_sessions) - 1, -1, -1):
        if isinstance(chat_sessions[i], dict) and chat_sessions[i].get("id") == session.get("id"):
            chat_sessions[i] = dict(session)
            break
    _save("chat_sessions.json", chat_sessions)

    return {
        "session_id": session.get("id"),
        "tool_messages": tool_messages,
        "model_message": model_msg,
        "generation_request": gr_row,
        "latency_ms": _lat_ms(),
        "requested_at": now_iso,
    }

def gemini_uploadFile(api_key_id, local_path, display_name=None, mime_type=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    def _lat_ms(): 
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^gmsk_[0-9A-Za-z]+$.")
    if not isinstance(local_path, str) or not local_path.strip():
        return _err("VALIDATION_ERROR", "local_path must be a non-empty string.")
    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "display_name must be a string when provided.")
    if mime_type is not None and not isinstance(mime_type, str):
        return _err("VALIDATION_ERROR", "mime_type must be a string when provided.")

    api_keys = _load("api_keys.json")
    uploaded_files = _load("uploaded_files.json")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")
    if key.get("provider") == "vertex_ai":
        return _err("UNAUTHORIZED", "File tools are not supported for provider='vertex_ai'.", provider=key.get("provider"))
    if key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_disabled")

    if not os.path.exists(local_path):
        return _err("NOT_FOUND", "local_path not found on local filesystem.", local_path=local_path)
    if not os.path.isfile(local_path):
        return _err("VALIDATION_ERROR", "local_path must refer to a file.", local_path=local_path)

    # compute sha256 + size
    sha256 = None
    size_bytes = None
    try:
        h = hashlib.sha256()
        total = 0
        with open(local_path, "rb") as f:
            while True:
                b = f.read(1024 * 1024)
                if not b:
                    break
                total += len(b)
                h.update(b)
        sha256 = h.hexdigest()
        size_bytes = total
    except OSError:
        return _err("NOT_FOUND", "Unable to read local_path.", local_path=local_path)

    # create upstream-like identifiers
    upstream_id = secrets.token_hex(12)
    upstream_name = f"files/{upstream_id}"
    uri = f"https://generativelanguage.googleapis.com/v1beta/{upstream_name}"

    # uniqueness (api_key_id, upstream_name)
    for r in uploaded_files:
        if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("upstream_name") == upstream_name:
            # extremely unlikely; regenerate once
            upstream_id = secrets.token_hex(12)
            upstream_name = f"files/{upstream_id}"
            uri = f"https://generativelanguage.googleapis.com/v1beta/{upstream_name}"
            break

    row = {
        "id": _new_id("gmfil"),
        "api_key_id": api_key_id,
        "upstream_name": upstream_name,
        "uri": uri,
        "display_name": display_name,
        "mime_type": mime_type,
        "size_bytes": int(size_bytes) if size_bytes is not None else None,
        "local_path": local_path,
        "sha256": sha256,
        "upstream_state": "ACTIVE",
        "status": "available",
        "uploaded_at": now_iso,
        "deleted_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    uploaded_files.append(row)
    _save("uploaded_files.json", uploaded_files)

    return {"file": row, "latency_ms": _lat_ms(), "uploaded": True, "requested_at": now_iso}

def gemini_listFiles(api_key_id, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _make_cursor(created_at, rid):
        payload = json.dumps({"created_at": created_at, "id": rid}, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return _b64url_encode(payload)

    def _read_cursor(tok):
        try:
            obj = json.loads(_b64url_decode(tok).decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "created_at" not in obj or "id" not in obj:
                return None
            if not isinstance(obj["created_at"], str) or not isinstance(obj["id"], str):
                return None
            return obj
        except Exception:
            return None

    start_t = time.time()
    api_keys = _load("api_keys.json")
    uploaded_files = _load("uploaded_files.json")
    gen_reqs = _load("generation_requests.json")

    def _log(status, used_key_id=None, error_code=None, error_message=None, tool_name="gemini_listFiles"):
        latency_ms = int((time.time() - start_t) * 1000)
        ts = _now()
        # Best-effort id generation
        def _new_id(prefix):
            import secrets
            return f"{prefix}_{secrets.token_hex(12)}"
        row = {
            "id": _new_id("gmr"),
            "api_key_id": used_key_id or api_key_id,
            "tool_name": tool_name,
            "model": "n/a",
            "is_stream": False,
            "chat_session_id": None,
            "prompt_text": None,
            "contents": None,
            "generation_config": None,
            "safety_settings": None,
            "tools_declarations": None,
            "function_call_request": None,
            "response_text": None,
            "response_raw": {"endpoint": tool_name, "status": status, "latency_ms": latency_ms},
            "usage": None,
            "status": "succeeded" if status == "ok" else "failed",
            "error_code": error_code,
            "error_message": error_message,
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        # If api key is missing, keep reference unset? Schema requires api_key_id not null, so only log when resolvable.
        if used_key_id is None:
            return
        gen_reqs.append(row)
        _save("generation_requests.json", gen_reqs)

    # Validate inputs
    if not isinstance(api_key_id, str) or re.match(r"^gmsk_[0-9A-Z]{3,}$", api_key_id) is None:
        return _err("VALIDATION_ERROR", "api_key_id is required and must match ^gmsk_[0-9A-Z]{3,}$")
    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 1000:
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log("validation_error", used_key_id=api_key_id, error_code="validation_error", error_message="Invalid page_size")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 1000")
    if page_token is not None and not isinstance(page_token, str):
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log("validation_error", used_key_id=api_key_id, error_code="validation_error", error_message="Invalid page_token")
        return _err("VALIDATION_ERROR", "page_token must be a string")

    # Authenticate/authorize (ambient; api_key_id is explicit identifier)
    key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Unknown api_key_id")
    if key_row.get("provider") != "google_ai_studio":
        _log("unauthorized", used_key_id=api_key_id, error_code="provider_not_supported", error_message="File APIs not supported for Vertex AI keys")
        return _err("UNAUTHORIZED", "This operation is only supported for Google AI Studio API keys")
    if key_row.get("status") != "active":
        _log("unauthorized", used_key_id=api_key_id, error_code="key_disabled", error_message="API key is not active")
        return _err("UNAUTHORIZED", "API key is not active", error_code="key_disabled")

    # Enforce daily request quota for this call (read also counts as request)
    if not isinstance(key_row.get("requests_today"), int) or not isinstance(key_row.get("daily_request_limit"), int):
        _log("failed", used_key_id=api_key_id, error_code="key_misconfigured", error_message="Key quota fields invalid")
        return _err("CONFLICT", "API key quota configuration is invalid")
    if key_row["requests_today"] + 1 > key_row["daily_request_limit"]:
        _log("quota_exceeded", used_key_id=api_key_id, error_code="quota_exceeded", error_message="Daily request limit exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", error_code="quota_exceeded")

    # Apply quota increment (observable dynamics)
    key_row["requests_today"] += 1
    key_row["updated_at"] = _now()
    # Persist api_keys
    for i, k in enumerate(api_keys):
        if k.get("id") == api_key_id:
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    # Filter items for this key
    items = [r for r in uploaded_files if r.get("api_key_id") == api_key_id]
    # Stable sort: created_at then id
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))
    items.sort(key=_sort_key)

    # Apply cursor
    start_index = 0
    if page_token:
        cursor = _read_cursor(page_token)
        if cursor is None:
            _log("validation_error", used_key_id=api_key_id, error_code="invalid_page_token", error_message="Could not decode page_token")
            return _err("VALIDATION_ERROR", "Invalid page_token")
        c_dt = _parse_dt(cursor["created_at"])
        if c_dt is None:
            _log("validation_error", used_key_id=api_key_id, error_code="invalid_page_token", error_message="Invalid cursor timestamp")
            return _err("VALIDATION_ERROR", "Invalid page_token")
        c_id = cursor["id"]

        # Find first item strictly after (created_at, id)
        for idx, r in enumerate(items):
            r_dt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            r_id = str(r.get("id") or "")
            if (r_dt, r_id) > (c_dt, c_id):
                start_index = idx
                break
        else:
            start_index = len(items)

    page = items[start_index:start_index + page_size]
    next_page_token = None
    if start_index + page_size < len(items) and len(page) > 0:
        last = page[-1]
        next_page_token = _make_cursor(last.get("created_at") or _now(), str(last.get("id") or ""))

    _log("ok", used_key_id=api_key_id, error_code=None, error_message=None)

    return {
        "files": [
            {
                "name": r.get("upstream_name"),
                "uri": r.get("uri"),
                "display_name": r.get("display_name"),
                "mime_type": r.get("mime_type"),
                "size_bytes": r.get("size_bytes"),
                "state": r.get("upstream_state"),
                "status": r.get("status"),
                "uploaded_at": r.get("uploaded_at"),
                "deleted_at": r.get("deleted_at"),
                "created_at": r.get("created_at"),
                "updated_at": r.get("updated_at"),
            }
            for r in page
        ],
        "next_page_token": next_page_token,
        "page_size": page_size,
        "total": len(items),
        "has_more": next_page_token is not None,
    }

