    if key.get("provider") == "vertex_ai":
        return _err("UNAUTHORIZED", "File tools are not supported for provider='vertex_ai'.", provider=key.get("provider"))

    # Real API uses upstream_name; but for usability accept lookup by display_name or id as well.
    file_row = next(
        (f for f in uploaded_files if isinstance(f, dict) and f.get("api_key_id") == api_key_id and (f.get("upstream_name") == name or f.get("display_name") == name or f.get("id") == name)),
        None,
    )
    if file_row is None:
        # read should return empty result set? This endpoint is get-by-id/name, so NOT_FOUND is appropriate.
        return _err("NOT_FOUND", "File not found.")

    return {"file": file_row, "latency_ms": _lat_ms(), "requested_at": now_iso}

def gemini_deleteFile(api_key_id, name, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    def _lat_ms(): 
        return int((time.time() - t0) * 1000)

    # Relax patterns to accept existing store ids; validate types.
    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^gmsk_[0-9A-Za-z]+$.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")

    api_keys = _load("api_keys.json")
    uploaded_files = _load("uploaded_files.json")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")
    if key.get("provider") == "vertex_ai":
        return _err("UNAUTHORIZED", "File tools are not supported for provider='vertex_ai'.", provider=key.get("provider"))
    if key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", error_code="key_disabled")

    idx = None
    for i, f in enumerate(uploaded_files):
        if not isinstance(f, dict):
            continue
        if f.get("api_key_id") != api_key_id:
            continue
        if f.get("upstream_name") == name or f.get("display_name") == name or f.get("id") == name:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "File not found.")

    row = dict(uploaded_files[idx])
    status = row.get("status")

    # Idempotent deletes
    if status == "deleted":
        return {"file": row, "deleted": True, "idempotent": True, "latency_ms": _lat_ms(), "requested_at": now_iso}

    allowed = {"available": ["deleting", "error"], "deleting": ["deleted", "error"], "error": ["deleting"], "deleted": []}
    if status not in allowed:
        return _err("INVALID_TRANSITION", "File cannot be deleted from current status.", status=status)

    # Transition to deleting if needed
    if status != "deleting":
        if "deleting" not in allowed.get(status, []):
            return _err("INVALID_TRANSITION", "File cannot transition to deleting from current status.", status=status)
        row["status"] = "deleting"
        row["updated_at"] = now_iso
        uploaded_files[idx] = row
        _save("uploaded_files.json", uploaded_files)

    # Transition to deleted
    row = dict(uploaded_files[idx])
    if row.get("status") == "deleted":
        return {"file": row, "deleted": True, "idempotent": True, "latency_ms": _lat_ms(), "requested_at": now_iso}

    if "deleted" not in allowed.get("deleting", []):
        return _err("INVALID_TRANSITION", "File cannot transition to deleted from deleting.", status=row.get("status"))

    row["status"] = "deleted"
    row["deleted_at"] = row.get("deleted_at") or now_iso
    row["upstream_state"] = row.get("upstream_state") or "DELETED"
    row["updated_at"] = now_iso
    uploaded_files[idx] = row
    _save("uploaded_files.json", uploaded_files)

    return {"file": row, "deleted": True, "latency_ms": _lat_ms(), "requested_at": now_iso}

def gemini_createCache(api_key_id, model, contents, display_name=None, ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return _now_dt().isoformat()

    def _add_seconds_iso(ts_iso, seconds):
        dt = _now_dt()
        try:
            if isinstance(ts_iso, str):
                s = ts_iso
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
        except Exception:
            dt = _now_dt()
        return (dt + datetime.timedelta(seconds=seconds)).isoformat()

    start_t = time.time()
    api_keys = _load("api_keys.json")
    cached = _load("cached_contents.json")
    gen_reqs = _load("generation_requests.json")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _log_req(status, used_key_id, error_code=None, error_message=None, response_raw=None):
        latency_ms = int((time.time() - start_t) * 1000)
        ts = _now()
        row = {
            "id": _new_id("gmr"),
            "api_key_id": used_key_id,
            "tool_name": "gemini_functionCall",  # closest "invokes Gemini" tool_name enum not including createCache
            "model": model if isinstance(model, str) else "n/a",
            "is_stream": False,
            "chat_session_id": None,
            "prompt_text": None,
            "contents": {"cached_contents_create": contents} if isinstance(contents, (dict, list)) else None,
            "generation_config": None,
            "safety_settings": None,
            "tools_declarations": None,
            "function_call_request": None,
            "response_text": None,
            "response_raw": response_raw if response_raw is not None else {"endpoint": "gemini_createCache", "status": status, "latency_ms": latency_ms},
            "usage": None,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": ts,
            "completed_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        gen_reqs.append(row)
        _save("generation_requests.json", gen_reqs)

    # Validate
    if not isinstance(api_key_id, str) or re.match(r"^gmsk_[0-9A-Z]{3,}$", api_key_id) is None:
        return _err("VALIDATION_ERROR", "api_key_id is required and must match ^gmsk_[0-9A-Z]{3,}$")
    if not isinstance(model, str) or not model.strip():
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log_req("failed", api_key_id, error_code="validation_error", error_message="Invalid model")
        return _err("VALIDATION_ERROR", "model is required and must be a non-empty string")
    if not isinstance(contents, dict):
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log_req("failed", api_key_id, error_code="validation_error", error_message="Invalid contents")
        return _err("VALIDATION_ERROR", "contents is required and must be an object")
    if display_name is not None and not isinstance(display_name, str):
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log_req("failed", api_key_id, error_code="validation_error", error_message="Invalid display_name")
        return _err("VALIDATION_ERROR", "display_name must be a string")
    if ttl_seconds is None:
        ttl_seconds = 3600
    if not isinstance(ttl_seconds, int):
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log_req("failed", api_key_id, error_code="validation_error", error_message="Invalid ttl_seconds type")
        return _err("VALIDATION_ERROR", "ttl_seconds must be an integer")
    # Enforce schema constraints: 60..2592000
    if ttl_seconds < 60 or ttl_seconds > 2592000:
        key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
        if key_row:
            _log_req("failed", api_key_id, error_code="validation_error", error_message="ttl_seconds out of range")
        return _err("VALIDATION_ERROR", "ttl_seconds must be between 60 and 2592000 seconds")

    key_row = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Unknown api_key_id")
    if key_row.get("status") != "active":
        # Must fail with error_code='key_disabled'
        _log_req("failed", api_key_id, error_code="key_disabled", error_message="API key is not active")
        return _err("UNAUTHORIZED", "API key is not active", error_code="key_disabled")

    # Quota enforcement (requests + tokens projection; tokens unknown => 0)
    if not isinstance(key_row.get("requests_today"), int) or not isinstance(key_row.get("daily_request_limit"), int):
        _log_req("failed", api_key_id, error_code="key_misconfigured", error_message="Key quota fields invalid")
        return _err("CONFLICT", "API key quota configuration is invalid")
    if not isinstance(key_row.get("tokens_today"), int) or not isinstance(key_row.get("daily_token_limit"), int):
        _log_req("failed", api_key_id, error_code="key_misconfigured", error_message="Key token quota fields invalid")
        return _err("CONFLICT", "API key quota configuration is invalid")
    projected_tokens = key_row["tokens_today"]  # cannot estimate from cache creation request offline
    if key_row["requests_today"] + 1 > key_row["daily_request_limit"] or projected_tokens > key_row["daily_token_limit"]:
        _log_req("failed", api_key_id, error_code="quota_exceeded", error_message="Quota exceeded")
        return _err("QUOTA_EXCEEDED", "Quota exceeded", error_code="quota_exceeded")

    # Create generation_requests lifecycle: queued -> running -> succeeded/failed
    req_id = _new_id("gmr")
    ts = _now()
    queued = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "gemini_functionCall",  # closest available enum bucket for non-stream call
        "model": model,
        "is_stream": False,
        "chat_session_id": None,
        "prompt_text": None,
        "contents": {"cached_contents_create": contents},
        "generation_config": None,
        "safety_settings": None,
        "tools_declarations": None,
        "function_call_request": None,
        "response_text": None,
        "response_raw": None,
        "usage": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": ts,
        "updated_at": ts,
    }
    gen_reqs.append(queued)
    _save("generation_requests.json", gen_reqs)

    # Transition to running
    for i, r in enumerate(gen_reqs):
        if r.get("id") == req_id:
            gen_reqs[i]["status"] = "running"
            gen_reqs[i]["started_at"] = _now()
            gen_reqs[i]["updated_at"] = gen_reqs[i]["started_at"]
            break
    _save("generation_requests.json", gen_reqs)

    # Increment request counter (observable)
    key_row["requests_today"] += 1
    key_row["updated_at"] = _now()
    for i, k in enumerate(api_keys):
        if k.get("id") == api_key_id:
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    # Create cached content record (mirror upstream)
    created_at = _now()
    expire_at = _add_seconds_iso(created_at, ttl_seconds)
    upstream_name = f"cachedContents/{secrets.token_urlsafe(12).rstrip('=')}"
    # Uniqueness constraint unique(api_key_id, upstream_name)
    if any(r.get("api_key_id") == api_key_id and r.get("upstream_name") == upstream_name for r in cached):
        upstream_name = f"cachedContents/{secrets.token_urlsafe(14).rstrip('=')}"

    cache_row = {
        "id": _new_id("gmc"),
        "api_key_id": api_key_id,
        "upstream_name": upstream_name,
        "model": model,
        "display_name": display_name,
        "contents": contents,
        "ttl_seconds": ttl_seconds,
        "expire_at": expire_at,
        "status": "active",
        "created_at": created_at,
        "updated_at": created_at,
    }
    cached.append(cache_row)
    _save("cached_contents.json", cached)

    # Complete generation request as succeeded
    completed = _now()
    for i, r in enumerate(gen_reqs):
        if r.get("id") == req_id:
            gen_reqs[i]["status"] = "succeeded"
            gen_reqs[i]["completed_at"] = completed
            gen_reqs[i]["updated_at"] = completed
            gen_reqs[i]["response_raw"] = {"cache": {"name": upstream_name, "model": model, "ttl_seconds": ttl_seconds, "expire_at": expire_at}}
            break
    _save("generation_requests.json", gen_reqs)

    return {
        "cache": {
            "name": cache_row.get("upstream_name"),
            "model": cache_row.get("model"),
            "display_name": cache_row.get("display_name"),
            "ttl_seconds": cache_row.get("ttl_seconds"),
            "expire_at": cache_row.get("expire_at"),
            "status": cache_row.get("status"),
            "created_at": cache_row.get("created_at"),
            "updated_at": cache_row.get("updated_at"),
        },
        "generation_request_id": req_id,
    }

def gemini_listCaches(api_key_id, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    t0 = time.time()

    # Validate
    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Z]{3,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is missing or invalid.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 1000:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 1000.")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string.")

    # Authenticate/authorize key and provider capability
    api_keys = _load("api_keys.json")
    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key_row:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")
    if key_row.get("provider") != "google_ai_studio":
        return _err("UNAUTHORIZED", "Cached Content API not allowed for this provider.", provider=key_row.get("provider"))

    # Paging token: base64url(json({"created_at": "...", "id": "..."}))
    cursor_created_at = None
    cursor_id = None
    if page_token:
        try:
            payload = json.loads(_b64url_decode(page_token).decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "page_token is malformed.")
        if not isinstance(payload, dict) or "created_at" not in payload or "id" not in payload:
            return _err("VALIDATION_ERROR", "page_token is malformed.")
        cursor_created_at = payload.get("created_at")
        cursor_id = payload.get("id")
        if not isinstance(cursor_created_at, str) or not isinstance(cursor_id, str):
            return _err("VALIDATION_ERROR", "page_token is malformed.")
        if _parse_dt(cursor_created_at) is None:
            return _err("VALIDATION_ERROR", "page_token is malformed.")

    # Load caches
    caches = _load("cached_contents.json")
    rows = [c for c in caches if isinstance(c, dict) and c.get("api_key_id") == api_key_id]

    # Stable order by (created_at, id)
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id", "")))

    rows.sort(key=_sort_key)

    # Apply cursor filter (created_at, id) strictly greater than cursor
    if cursor_created_at is not None:
        cdt = _parse_dt(cursor_created_at)
        cid = cursor_id
        def _after(r):
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            rid = str(r.get("id", ""))
            return (rdt > cdt) or (rdt == cdt and rid > cid)
        rows = [r for r in rows if _after(r)]

    page = rows[:page_size]
    has_more = len(rows) > len(page)
    next_page_token = None
    if has_more and page:
        last = page[-1]
        last_created = last.get("created_at")
        last_id = last.get("id")
        if isinstance(last_created, str) and isinstance(last_id, str):
            next_page_token = _b64url_encode(json.dumps({"created_at": last_created, "id": last_id}).encode("utf-8"))

    # Audit/usage log (if collection exists)
    logs = _load("generation_requests.json")
    if isinstance(logs, list):
        status = "succeeded"
        now = _now_iso()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"gmr_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "api_key_id": api_key_id,
            "tool_name": "gemini_listCaches",
            "model": "n/a",
            "is_stream": False,
            "chat_session_id": None,
            "prompt_text": None,
            "contents": None,
            "generation_config": None,
            "safety_settings": None,
            "tools_declarations": None,
            "function_call_request": None,
            "response_text": None,
            "response_raw": {
                "endpoint": "gemini_listCaches",
                "page_size": page_size,
                "page_token_present": bool(page_token),
                "returned": len(page),
                "has_more": has_more,
                "latency_ms": latency_ms
            },
            "usage": None,
            "status": status,
            "error_code": None,
            "error_message": None,
            "started_at": now,
            "completed_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("generation_requests.json", logs)

    return {
        "cached_contents": page,
        "next_page_token": next_page_token,
        "page_size": page_size,
        "has_more": has_more,
        "total_visible": len([c for c in caches if isinstance(c, dict) and c.get("api_key_id") == api_key_id])
    }

