def gemini_updateCache(api_key_id, name, display_name=None, ttl_seconds=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    def _lat_ms(): 
        return int((time.time() - t0) * 1000)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.astimezone(datetime.timezone.utc) if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt.astimezone(datetime.timezone.utc) if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    # Validate (do not over-reject: tool schema says ttl_seconds minimum 1, but business rules enforce [60, 2592000])
    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^gmsk_[0-9A-Za-z]+$.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if display_name is None and ttl_seconds is None:
        return _err("VALIDATION_ERROR", "Provide display_name and/or ttl_seconds.")
    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "display_name must be a string when provided.")
    if ttl_seconds is not None:
        if not isinstance(ttl_seconds, int):
            return _err("VALIDATION_ERROR", "ttl_seconds must be an integer.")
        if ttl_seconds < 60 or ttl_seconds > 2592000:
            return _err("VALIDATION_ERROR", "ttl_seconds must be between 60 and 2592000 seconds.")

    api_keys = _load("api_keys.json")
    caches = _load("cached_contents.json")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")

    idx = None
    for i, c in enumerate(caches):
        if not isinstance(c, dict):
            continue
        if c.get("api_key_id") != api_key_id:
            continue
        if c.get("upstream_name") == name or c.get("display_name") == name or c.get("id") == name:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Cache not found.")

    cache = dict(caches[idx])
    if ttl_seconds is not None and cache.get("status") != "active":
        # business rule
        return _err("CONFLICT", "Cache is not active; ttl_seconds cannot be updated.", error_code="cache_not_active", status=cache.get("status"))

    # Apply updates
    if display_name is not None:
        cache["display_name"] = display_name
    if ttl_seconds is not None:
        cache["ttl_seconds"] = int(ttl_seconds)
        created = _parse_dt(cache.get("created_at")) or now
        expire_at = created + datetime.timedelta(seconds=int(ttl_seconds))
        cache["expire_at"] = expire_at.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    cache["updated_at"] = now_iso

    caches[idx] = cache
    _save("cached_contents.json", caches)
    return {"cache": cache, "latency_ms": _lat_ms(), "requested_at": now_iso}

def gemini_deleteCache(api_key_id, name, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    def _lat_ms(): 
        return int((time.time() - t0) * 1000)

    if not isinstance(api_key_id, str) or not re.match(r"^gmsk_[0-9A-Za-z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must be a string matching ^gmsk_[0-9A-Za-z]+$.")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")

    api_keys = _load("api_keys.json")
    caches = _load("cached_contents.json")

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
    if not key:
        return _err("UNAUTHORIZED", "Unknown api_key_id.")

    idx = None
    for i, c in enumerate(caches):
        if not isinstance(c, dict):
            continue
        if c.get("api_key_id") != api_key_id:
            continue
        if c.get("upstream_name") == name or c.get("display_name") == name or c.get("id") == name:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Cache not found.")

    cache = dict(caches[idx])
    status = cache.get("status")

    # Idempotent
    if status == "deleted":
        return {"cache": cache, "deleted": True, "idempotent": True, "latency_ms": _lat_ms(), "requested_at": now_iso}

    allowed = {
        "active": ["expired", "deleting", "error"],
        "expired": ["deleting", "deleted"],
        "deleting": ["deleted", "error"],
        "deleted": [],
        "error": ["deleting"],
    }
    if status not in allowed:
        return _err("INVALID_TRANSITION", "Cache cannot be deleted from current status.", status=status)

    # Transition to deleting if not already
    if status != "deleting":
        if "deleting" not in allowed.get(status, []):
            return _err("INVALID_TRANSITION", "Cache cannot transition to deleting from current status.", status=status)
        cache["status"] = "deleting"
        cache["updated_at"] = now_iso
        caches[idx] = cache
        _save("cached_contents.json", caches)

    # Transition to deleted
    cache = dict(caches[idx])
    if cache.get("status") == "deleted":
        return {"cache": cache, "deleted": True, "idempotent": True, "latency_ms": _lat_ms(), "requested_at": now_iso}

    cache["status"] = "deleted"
    cache["updated_at"] = now_iso
    caches[idx] = cache
    _save("cached_contents.json", caches)

    return {"cache": cache, "deleted": True, "latency_ms": _lat_ms(), "requested_at": now_iso}

def gemini_listGenerationRequests(api_key_id=None, chat_session_id=None, status=None, model=None, is_stream=None, limit=None, page_token=None, created_at_lte=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt.astimezone(datetime.timezone.utc) if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _enc_cursor(dt, _id):
        payload = (dt.replace(microsecond=0).isoformat().replace("+00:00", "Z") + "|" + _id).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _dec_cursor(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok.strip():
            return None
        t = tok.strip()
        pad = "=" * (-len(t) % 4)
        try:
            raw = base64.urlsafe_b64decode((t + pad).encode("ascii")).decode("utf-8")
        except Exception:
            return "INVALID"
        if "|" not in raw:
            return "INVALID"
        a, b = raw.split("|", 1)
        dt = _parse_dt(a)
        if dt is None or not b:
            return "INVALID"
        return (dt, b)

    def _audit(used_key_id, ok, meta=None):
        logs = _load("generation_requests.json")
        ts = _now_iso()
        logs.append({
            "id": "gmrq_audit_" + ts.replace(":", "").replace("-", "").replace("Z", "") + "_" + str(int((time.time() % 1) * 1_000_000)),
            "api_key_id": used_key_id if used_key_id else "gmsk_audit",
            "tool_name": "gemini_listGenerationRequests",
            "model": "audit",
            "is_stream": False,
            "chat_session_id": None,
            "prompt_text": None,
            "contents": {"filters": meta or {}},
            "generation_config": None,
            "safety_settings": None,
            "tools_declarations": None,
            "function_call_request": None,
            "response_text": None,
            "response_raw": {"status": "ok" if ok else "error", "latency_ms": int((time.time() - t0) * 1000)},
            "usage": None,
            "status": "succeeded" if ok else "failed",
            "error_code": None if ok else "VALIDATION_ERROR",
            "error_message": None if ok else "request failed",
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        })
        _save("generation_requests.json", logs)

    gen_reqs = _load("generation_requests.json")

    # Validate filters
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.startswith("gmsk_")):
        _audit(api_key_id, False, {"api_key_id": api_key_id})
        return _err("VALIDATION_ERROR", "Invalid api_key_id filter.")
    # IMPORTANT: parameter schema says ^gmsc_... but datastore uses gmsn_ for chat_sessions; accept both.
    if chat_session_id is not None and (not isinstance(chat_session_id, str) or not (chat_session_id.startswith("gmsn_") or chat_session_id.startswith("gmsc_"))):
        _audit(api_key_id, False, {"chat_session_id": chat_session_id})
        return _err("VALIDATION_ERROR", "Invalid chat_session_id filter.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _audit(api_key_id, False, {"status": status})
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if is_stream is not None and not isinstance(is_stream, bool):
        _audit(api_key_id, False, {"is_stream": is_stream})
        return _err("VALIDATION_ERROR", "is_stream must be a boolean.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _audit(api_key_id, False, {"limit": limit})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if created_at_lte is not None:
        if not isinstance(created_at_lte, str) or _parse_dt(created_at_lte) is None:
            _audit(api_key_id, False, {"created_at_lte": created_at_lte})
            return _err("VALIDATION_ERROR", "created_at_lte must be an ISO date-time.")

    cursor = None
    if page_token is not None:
        cursor = _dec_cursor(page_token)
        if cursor == "INVALID":
            _audit(api_key_id, False, {"page_token": page_token})
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    # Filter only true generation requests (exclude prior broken audit ids if any); keep gmrq_ prefix
    rows = [r for r in gen_reqs if isinstance(r, dict) and isinstance(r.get("id"), str) and r.get("id", "").startswith("gmrq_")]

    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if chat_session_id is not None:
        rows = [r for r in rows if r.get("chat_session_id") == chat_session_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if model is not None:
        if not isinstance(model, str):
            _audit(api_key_id, False, {"model": model})
            return _err("VALIDATION_ERROR", "model must be a string.")
        rows = [r for r in rows if r.get("model") == model]
    if is_stream is not None:
        rows = [r for r in rows if bool(r.get("is_stream")) == is_stream]
    if created_at_lte is not None:
        ub = _parse_dt(created_at_lte)
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)) <= ub]

    # Sort reverse chronological by (created_at, id)
    def _rk(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    rows.sort(key=_rk, reverse=True)

    # Apply cursor (exclusive): created_at/id less than cursor
    if cursor is not None:
        cdt, cid = cursor
        def _after_cursor(r):
            dt, rid = _rk(r)
            # since sorted desc, we keep those strictly older/smaller than cursor
            return (dt < cdt) or (dt == cdt and (rid or "") < cid)
        rows = [r for r in rows if _after_cursor(r)]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_page_token = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        next_page_token = _enc_cursor(last_dt, last.get("id") or "")

    _audit(api_key_id, True, {"api_key_id": api_key_id, "chat_session_id": chat_session_id, "status": status, "model": model, "is_stream": is_stream, "limit": limit})

    return {
        "generation_requests": page,
        "total": total,
        "has_more": has_more,
        "next_page_token": next_page_token,
    }

