def gemini_cancelGenerationRequest(id, reason=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    def _lat_ms(): 
        return int((time.time() - t0) * 1000)

    # Validate (do not over-reject beyond schema)
    if not isinstance(id, str) or not re.match(r"^gmrq_[0-9A-Za-z]+$", id):
        return _err("VALIDATION_ERROR", "id must match ^gmrq_[0-9A-Za-z]+$.")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string when provided.")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason must have maxLength 500.")

    gen_reqs = _load("generation_requests.json")
    idx = next((i for i, r in enumerate(gen_reqs) if isinstance(r, dict) and r.get("id") == id), None)
    if idx is None:
        return _err("NOT_FOUND", "Generation request not found.")

    row = dict(gen_reqs[idx])
    status = row.get("status")

    # Refuse cancellation of terminal requests with CONFLICT
    if status in ("succeeded", "failed", "cancelled"):
        return _err("CONFLICT", "Cannot cancel a terminal generation request.", status=status)

    # Only queued/running may transition to cancelled
    if status not in ("queued", "running"):
        return _err("INVALID_TRANSITION", "Generation request cannot be cancelled from current status.", status=status)

    # Apply transition
    row["status"] = "cancelled"
    row["error_code"] = "cancelled"
    row["error_message"] = (reason.strip() if isinstance(reason, str) and reason.strip() else "Cancelled by user.")
    if not row.get("started_at"):
        row["started_at"] = now_iso
    row["completed_at"] = now_iso
    row["updated_at"] = now_iso

    gen_reqs[idx] = row
    _save("generation_requests.json", gen_reqs)

    return {"generation_request": row, "latency_ms": _lat_ms(), "requested_at": now_iso}

def gemini_updateApiKey(id, display_name=None, status=None, daily_request_limit=None, daily_token_limit=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0350000" if __import__("os").path.isdir("./environment_mix/0350000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, used_key_id=None, meta=None):
        logs = _load("generation_requests.json")
        ts = _now_iso()
        rid = "gmrq_audit_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + str(int((time.time() % 1) * 1_000_000))
        row = {
            "id": rid,
            "api_key_id": used_key_id if used_key_id is not None else "gmsk_audit",
            "tool_name": "gemini_updateApiKey",
            "model": "audit",
            "is_stream": False,
            "chat_session_id": None,
            "prompt_text": None,
            "contents": meta if isinstance(meta, dict) else None,
            "generation_config": None,
            "safety_settings": None,
            "tools_declarations": None,
            "function_call_request": None,
            "response_text": None,
            "response_raw": {"status": status_str, "latency_ms": int((time.time() - t0) * 1000)},
            "usage": None,
            "status": "succeeded" if status_str == "ok" else "failed",
            "error_code": None if status_str == "ok" else status_str,
            "error_message": None if status_str == "ok" else (meta.get("error_message") if isinstance(meta, dict) else None),
            "started_at": ts,
            "completed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("generation_requests.json", logs)

    # Validate id
    if not isinstance(id, str) or not id.startswith("gmsk_") or not id[5:].isalnum():
        _log("VALIDATION_ERROR", None, {"id": id, "error_message": "id must match ^gmsk_[0-9A-Za-z]+$"})
        return _err("VALIDATION_ERROR", "Invalid id.")

    # Validate fields
    if display_name is not None:
        if not isinstance(display_name, str):
            _log("VALIDATION_ERROR", None, {"id": id, "error_message": "display_name must be string"})
            return _err("VALIDATION_ERROR", "Invalid display_name.")
        if len(display_name) < 1 or len(display_name) > 120:
            _log("VALIDATION_ERROR", None, {"id": id, "error_message": "display_name length must be 1..120"})
            return _err("VALIDATION_ERROR", "Invalid display_name length.")
    allowed_status = {"active", "disabled", "revoked"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("VALIDATION_ERROR", None, {"id": id, "error_message": "status must be active|disabled|revoked"})
            return _err("VALIDATION_ERROR", "Invalid status.")
    if daily_request_limit is not None:
        if not isinstance(daily_request_limit, int) or daily_request_limit < 0:
            _log("VALIDATION_ERROR", None, {"id": id, "error_message": "daily_request_limit must be integer >= 0"})
            return _err("VALIDATION_ERROR", "Invalid daily_request_limit.")
    if daily_token_limit is not None:
        if not isinstance(daily_token_limit, int) or daily_token_limit < 0:
            _log("VALIDATION_ERROR", None, {"id": id, "error_message": "daily_token_limit must be integer >= 0"})
            return _err("VALIDATION_ERROR", "Invalid daily_token_limit.")

    if display_name is None and status is None and daily_request_limit is None and daily_token_limit is None:
        _log("VALIDATION_ERROR", None, {"id": id, "error_message": "no mutable fields provided"})
        return _err("VALIDATION_ERROR", "No updatable fields provided.")

    keys = _load("api_keys.json")
    idx = None
    k = None
    for i, r in enumerate(keys):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            k = r
            break

    if k is None:
        _log("NOT_FOUND", None, {"id": id, "error_message": "api key not found"})
        return _err("NOT_FOUND", "API key not found.", id=id)

    # Enforce provider=vertex_ai implies project/location not null (existing record should already comply; validate defensively)
    if k.get("provider") == "vertex_ai":
        if not k.get("project") or not k.get("location"):
            _log("CONFLICT", id, {"id": id, "error_message": "vertex_ai key missing project/location"})
            return _err("CONFLICT", "Vertex AI keys must have project and location set.", id=id)

    # Lifecycle transitions
    transitions = {
        "active": {"disabled", "revoked"},
        "disabled": {"active", "revoked"},
        "revoked": set(),
    }
    if status is not None:
        cur = k.get("status")
        if cur not in transitions:
            _log("CONFLICT", id, {"id": id, "error_message": "unknown current status"})
            return _err("CONFLICT", "API key is in an unknown lifecycle state.", id=id)
        if status != cur:
            if status not in transitions.get(cur, set()):
                _log("CONFLICT", id, {"id": id, "error_message": f"invalid transition {cur}->{status}"})
                return _err("CONFLICT", "Invalid status transition.", id=id, from_status=cur, to_status=status)

    # Apply updates
    now = _now_iso()
    if display_name is not None:
        k["display_name"] = display_name
    if daily_request_limit is not None:
        k["daily_request_limit"] = daily_request_limit
        if isinstance(k.get("requests_today"), int) and k["requests_today"] < 0:
            k["requests_today"] = 0
    if daily_token_limit is not None:
        k["daily_token_limit"] = daily_token_limit
        if isinstance(k.get("tokens_today"), int) and k["tokens_today"] < 0:
            k["tokens_today"] = 0
    if status is not None:
        k["status"] = status

    k["updated_at"] = now
    keys[idx] = k
    _save("api_keys.json", keys)

    _log("ok", id, {"id": id, "updated_fields": {"display_name": display_name is not None, "status": status, "daily_request_limit": daily_request_limit is not None, "daily_token_limit": daily_token_limit is not None}})
    return {"api_key": k}
